FAIR = ("# (топ, шын белгі, болжам): 1 - «оқушыға қосымша сабақ ұсыну керек»\n"
        "data = (\n"
        "    [('қала', 1, 1)] * 40 + [('қала', 1, 0)] * 10 + [('қала', 0, 0)] * 430 + [('қала', 0, 1)] * 20 +\n"
        "    [('ауыл', 1, 1)] * 6 + [('ауыл', 1, 0)] * 9 + [('ауыл', 0, 0)] * 33 + [('ауыл', 0, 1)] * 2\n"
        ")\n\n"
        "def group_stats(g):\n"
        "    rows = [r for r in data if r[0] == g]\n"
        "    pos_rate = sum(p for _, _, p in rows) / len(rows)\n"
        "    tpr = sum(p for _, y, p in rows if y) / sum(y for _, y, _ in rows)\n"
        "    acc = sum(y == p for _, y, p in rows) / len(rows)\n"
        "    return len(rows), pos_rate, tpr, acc\n\n"
        "overall = sum(y == p for _, y, p in data) / len(data)\n"
        "print(f'жалпы дәлдік: {overall:.3f}')\n"
        "for g in ('қала', 'ауыл'):\n"
        "    n, pr, tpr, acc = group_stats(g)\n"
        "    print(f'{g:5} n={n:3}: «иә» үлесі {pr:.2f}, TPR (recall) {tpr:.2f}, дәлдік {acc:.2f}')\n"
        "_, pr1, t1, _ = group_stats('қала'); _, pr2, t2, _ = group_stats('ауыл')\n"
        "print(f'демографиялық паритет айырмасы: {abs(pr1 - pr2):.2f}, тең мүмкіндік айырмасы: {abs(t1 - t2):.2f}')")

