IMPOSS = ("def ppv(p, tpr, fpr):\n"
          "    \"\"\"оң болжамның дұрыстығы (precision) базалық деңгей p бойынша\"\"\"\n"
          "    return p * tpr / (p * tpr + (1 - p) * fpr)\n\n"
          "groups = {'қала': 0.10, 'ауыл': 0.30}            # көмек керек оқушылардың базалық үлесі\n"
          "TPR, FPR = 0.80, 0.10                             # екі топта БІРДЕЙ қате деңгейлері\n"
          "for g, p in groups.items():\n"
          "    print(f'{g:5}: p = {p:.2f}, TPR = {TPR}, FPR = {FPR} -> PPV = {ppv(p, TPR, FPR):.3f}')\n\n"
          "# PPV-ны тең ету үшін (мысалы, 0.47) ауылда FPR қандай болуы керек?\n"
          "target = ppv(0.10, TPR, FPR)\n"
          "p = 0.30\n"
          "fpr_needed = p * TPR * (1 - target) / (target * (1 - p))\n"
          "print(f'ауылда PPV = {target:.3f} болуы үшін FPR = {fpr_needed:.3f} керек (TPR бірдей болса) - қате деңгейлері теңдігі бұзылады')")

