PERM = ("import random\n\n"
        "rng = random.Random(8)\n"
        "FEATURES = ['сабаққа қатысу', 'үй жұмысы', 'парта нөмірі']\n"
        "rows = []\n"
        "for _ in range(400):\n"
        "    att, hw, desk = rng.random(), rng.random(), rng.randint(1, 15)\n"
        "    y = (0.6 * att + 0.4 * hw + rng.gauss(0, 0.1)) < 0.45       # көмек керек\n"
        "    rows.append(([att, hw, desk], y))\n\n"
        "def model(x):\n"
        "    return 0.6 * x[0] + 0.4 * x[1] < 0.45                        # парта нөмірін қолданбайды\n\n"
        "def accuracy(data):\n"
        "    return sum(model(x) == y for x, y in data) / len(data)\n\n"
        "base = accuracy(rows)\n"
        "print(f'бастапқы дәлдік: {base:.3f}')\n"
        "for j, name in enumerate(FEATURES):\n"
        "    drops = []\n"
        "    for _ in range(5):\n"
        "        col = [x[j] for x, _ in rows]\n"
        "        rng.shuffle(col)\n"
        "        permuted = [(x[:j] + [c] + x[j + 1:], y) for (x, y), c in zip(rows, col)]\n"
        "        drops.append(base - accuracy(permuted))\n"
        "    print(f'{name:16}: маңыздылық {sum(drops) / len(drops):.3f}')")

