ADV = ("w = [2.0, -1.5, 0.5]          # сызықтық модель: w·x + b > 0 -> «қабылдансын»\n"
       "b = -0.4\n"
       "x = [0.5, 0.3, 0.2]\n\n"
       "score = lambda v: sum(wi * vi for wi, vi in zip(w, v)) + b\n"
       "print(f'бастапқы ұпай: {score(x):.3f} ->', 'иә' if score(x) > 0 else 'жоқ')\n\n"
       "# L∞ бойынша ең кіші ауытқу: әр координатаны ε-ға, ұпайды азайтатын бағытта\n"
       "l1 = sum(abs(wi) for wi in w)\n"
       "eps_star = score(x) / l1\n"
       "print(f'шешімді өзгерту үшін ең кіші ε (әр ерекшелікке): {eps_star:.4f}')\n"
       "sign = lambda t: (t > 0) - (t < 0)\n"
       "for eps in (eps_star * 0.99, eps_star * 1.01):\n"
       "    x_adv = [xi - eps * sign(wi) for xi, wi in zip(x, w)]\n"
       "    print(f'ε = {eps:.4f}: ұпай {score(x_adv):+.4f} ->', 'иә' if score(x_adv) > 0 else 'жоқ')")

